const request = $input.first().json;
const body = request.body ?? request;
const payload = body.payload ?? {};
const quality = payload.quality_summary ?? {};
const privacy = payload.privacy ?? {};

const errors = [];
if (body.event_type !== 'mra_quality_report_ready') errors.push('event_type ไม่ถูกต้อง');
if (!payload.schema_version) errors.push('ไม่พบ schema_version');
if (!quality.readiness_status) errors.push('ไม่พบ readiness_status');
if (typeof quality.fact_rows !== 'number') errors.push('ไม่พบจำนวน fact_rows');
if (privacy.contains_patient_identifiers !== false) errors.push('Payload อาจมีข้อมูลระบุตัวผู้ป่วย');

const accepted = errors.length === 0 && quality.failed_checks === 0;
return [{
  json: {
    accepted,
    response_status: accepted ? 'RECEIVED' : 'REVIEW_REQUIRED',
    received_at: new Date().toISOString(),
    source: body.source ?? 'unknown',
    run_id: payload.run_id ?? null,
    readiness_status: quality.readiness_status ?? 'UNKNOWN',
    fact_rows: quality.fact_rows ?? 0,
    join_coverage_rate: quality.join_coverage_rate ?? null,
    failed_checks: quality.failed_checks ?? null,
    warning_checks: quality.warning_checks ?? null,
    errors,
    message_th: accepted
      ? `n8n รับผล MRA สำเร็จ จำนวน ${quality.fact_rows.toLocaleString('th-TH')} แถว สถานะ ${quality.readiness_status}`
      : `ต้องตรวจสอบข้อมูลก่อนดำเนินการ: ${errors.join(', ') || 'Quality check ไม่ผ่าน'}`,
    prompt_th: body.prompt_th ?? ''
  }
}];
